def penalize_invalid_latex_structure(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        content = completion[0]['content']
        score = 0.0

        # Check for unclosed tags
        if '<thinking>' in content and '</thinking>' not in content:
            score -= 1.5
        if '<solution>' in content and '</solution>' not in content:
            score -= 1.5

        # Check for malformed LaTeX in solution
        sol_match = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)
        if sol_match:
            sol_text = sol_match.group(1)
            # Look for common malformed patterns like unbalanced brackets or incomplete commands
            if re.search(r'\\frac\{[^}]*$', sol_text) or re.search(r'\\sqrt\{[^}]*$', sol_text):
                score -= 1.0
            if sol_text.count('[') != sol_text.count(']'):
                score -= 0.5
            if sol_text.count('{') != sol_text.count('}'):
                score -= 0.5

            # Check if solution is just a raw LaTeX block without a clear final number
            # This is a heuristic: if it's long and doesn't end with a number or boxed, it's likely bad
            if len(sol_text) > 100 and not re.search(r'\d+\s*$', sol_text.strip()) and '\\boxed' not in sol_text:
                score -= 0.5
        else:
            # No solution tag found
            score -= 1.0

        scores.append(score)
    return scores

def reward_exact_numeric_match(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        content = completion[0]['content']
        score = 0.0

        sol_match = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)
        if not sol_match:
            scores.append(-1.0)
            continue

        pred_text = sol_match.group(1).strip()

        if is_correct(pred_text, true_answer):
            # Bonus for clean integer format if GT is integer
            if re.fullmatch(r'-?\d+', true_answer.strip()):
                if re.fullmatch(r'-?\d+', pred_text.strip()):
                    score += 5.0
                else:
                    score += 4.0
            else:
                score += 5.0
        else:
            # Check if it's a close numeric error
            try:
                # Extract numbers for comparison
                pred_num = float(re.search(r'-?\d+\.?\d*', pred_text).group())
                gt_num = float(re.search(r'-?\d+\.?\d*', true_answer).group())
                if abs(pred_num - gt_num) <= 1:
                    score += 1.0 # Small reward for being close
                elif abs(pred_num - gt_num) <= 10:
                    score += 0.5
                else:
                    score -= 1.0
            except:
                score -= 1.0
        scores.append(score)
    return scores

def penalize_repetitive_thinking_lines(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        content = completion[0]['content']
        score = 0.0

        think_match = re.search(r'<thinking>(.*?)</thinking>', content, re.DOTALL)
        if think_match:
            think_text = think_match.group(1)
            lines = [line.strip() for line in think_text.split('\n') if line.strip()]

            max_repeat = 1
            current_repeat = 1
            for i in range(1, len(lines)):
                if lines[i] == lines[i-1]:
                    current_repeat += 1
                    max_repeat = max(max_repeat, current_repeat)
                else:
                    current_repeat = 1

            if max_repeat > 3:
                score -= 1.5
            elif max_repeat > 2:
                score -= 0.5
        scores.append(score)
    return scores

def reward_concise_solution_tag(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        content = completion[0]['content']
        score = 0.0

        sol_match = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)
        if sol_match:
            sol_text = sol_match.group(1).strip()

            # Reward short, clear answers
            if len(sol_text) < 50:
                score += 1.0
            elif len(sol_text) < 100:
                score += 0.5
            else:
                score -= 0.5

            # Penalize if it contains full sentences or explanations
            if re.search(r'\b(because|since|therefore|thus|we have|let\s)', sol_text, re.IGNORECASE):
                score -= 1.0
        else:
            score -= 1.0

        scores.append(score)
    return scores

def reward_correct_intermediate_logic(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        content = completion[0]['content']
        score = 0.0

        think_match = re.search(r'<thinking>(.*?)</thinking>', content, re.DOTALL)
        if think_match:
            think_text = think_match.group(1)

            # Count equation-like lines
            eq_lines = re.findall(r'\\\[.*?\\\]|\\\(.*?\\\)', think_text, re.DOTALL)
            if len(eq_lines) >= 3:
                score += 1.0
            elif len(eq_lines) >= 1:
                score += 0.5

            # Check for logical connectors
            if re.search(r'\b(therefore|thus|hence|so|implies|means)\b', think_text, re.IGNORECASE):
                score += 0.5
        scores.append(score)
    return scores

def penalize_hallucinated_complexity(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        content = completion[0]['content']
        score = 0.0

        think_match = re.search(r'<thinking>(.*?)</thinking>', content, re.DOTALL)
        sol_match = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)

        if think_match and sol_match:
            think_len = len(think_match.group(1))
            sol_text = sol_match.group(1).strip()

            # If thinking is very long but answer is short and incorrect, penalize
            if not is_correct(sol_text, true_answer):
                if think_len > 1000:
                    score -= 1.0
                elif think_len > 500:
                    score -= 0.5
        scores.append(score)
    return scores

def reward_answer_in_thinking(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        content = completion[0]['content']
        score = 0.0

        think_match = re.search(r'<thinking>(.*?)</thinking>', content, re.DOTALL)
        sol_match = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)

        if think_match and sol_match:
            think_text = think_match.group(1)
            sol_text = sol_match.group(1).strip()

            # Extract the core number from the solution
            sol_num_match = re.search(r'-?\d+\.?\d*', sol_text)
            if sol_num_match:
                sol_num = sol_num_match.group()
                # Check if this number appears in the thinking block
                if sol_num in think_text:
                    score += 1.0
                else:
                    score -= 0.5
            else:
                # If no number in solution, check if any number in thinking matches GT
                if is_correct(sol_text, true_answer):
                    score += 1.0
        scores.append(score)
    return scores

def penalize_missing_structure(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        content = completion[0]['content']
        score = 0.0

        has_think = '<thinking>' in content and '</thinking>' in content
        has_sol = '<solution>' in content and '</solution>' in content

        if has_think and has_sol:
            score += 0.5
        elif has_think or has_sol:
            score -= 0.5
        else:
            score -= 1.5

        # Check for empty tags
        think_match = re.search(r'<thinking>(.*?)</thinking>', content, re.DOTALL)
        sol_match = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)

        if think_match and not think_match.group(1).strip():
            score -= 0.5
        if sol_match and not sol_match.group(1).strip():
            score -= 0.5

        scores.append(score)
    return scores

def reward_integer_consistency(prompts, completions, answer, **kwargs):
    import re
    scores = []
    for completion, true_answer in zip(completions, answer):
        content = completion[0]['content']
        score = 0.0

        sol_match = re.search(r'<solution>(.*?)</solution>', content, re.DOTALL)
        if sol_match:
            sol_text = sol_match.group(1).strip()

            # Check if GT is an integer
            gt_is_int = bool(re.fullmatch(r'-?\d+', true_answer.strip()))

            # Check if prediction is an integer
            pred_num_match = re.search(r'-?\d+\.?\d*', sol_text)
            if pred_num_match:
                pred_str = pred_num_match.group()
                pred_is_int = bool(re.fullmatch(r'-?\d+', pred_str))

                if gt_is_int:
                    if pred_is_int:
                        score += 1.0
                    else:
                        score -= 1.0
                else:
                    # If GT is not integer, no strong penalty for integer pred, but slight reward for matching type
                    if not pred_is_int:
                        score += 0.5
            else:
                score -= 0.5
        else:
            score -= 1.0

        scores.append(score)
    return scores

